src/App.css:
#root { min-height:100svh; }
.maya-shell {
  --ink:#fff8ed; --muted:#e9ecff; --accent:#d9cdff; --gold:#ffdfa0;
  --surface:linear-gradient(135deg,#ced0ff69,#5c74c980 50%,#c6c1ff55);
  --line:#e9e3ffc9; --field:#e7e8ffed; --field-ink:#241a62;
  --bg-art:url('/art/astral-blue.png');
  width:min(100%,520px);margin-inline:auto;min-height:100svh;min-height:100dvh;
  position:relative;isolation:isolate;display:flex;flex-direction:column;
  gap:10px;padding:max(12px,env(safe-area-inset-top)) 12px max(10px,env(safe-area-inset-bottom));
  color:var(--ink);background:#3d4c9a;
}
.maya-shell::before {content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;background:var(--bg-art) center top/cover;max-width:520px;margin:auto;}
.theme-astral-gold { --bg-art:url('/art/astral-gold.png'); --gold:#fff0c9;--accent:#fff0c9;--surface:linear-gradient(135deg,#fae1af88,#6a47757d 58%,#efc17480);background:#936c53; }
.theme-plain-light { --ink:#211465;--muted:#605d7e;--accent:#5336d2;--gold:#cf931d;--surface:#ffffffed;--line:#dadcfa;--field:#f4f3ff;--field-ink:#241a62;background:#f6f7ff; }
.theme-plain-light::before {background:radial-gradient(at 15% 15%,#dce8ff88,transparent 45%),#f7f8ff;}
.glass { background:var(--surface);border:1px solid var(--line);border-radius:24px;box-shadow:inset 0 1px 0 #fff9,0 5px 18px #22264c20;backdrop-filter:blur(10px); }
button,a,input,textarea,select { -webkit-tap-highlight-color:transparent; }
a { color:inherit; }
.maya-icon { width:25px;height:25px;flex:0 0 auto; }
.icon-button {width:42px;height:42px;display:grid;place-items:center;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--ink);text-decoration:none;}
.theme-plain-light .icon-button {color:var(--accent);}
.header-actions {display:flex;gap:7px;}
#maya-content {flex:1;min-width:0;display:flex;flex-direction:column;}
#maya-content:focus {outline:none;}
.dashboard-home {flex:1;display:flex;flex-direction:column;gap:10px;}
.dashboard-topbar {display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:54px;}
.dashboard-profile {display:flex;align-items:center;gap:8px;min-width:0;}
.dashboard-avatar {width:49px;height:49px;flex:0 0 49px;object-fit:contain;border-radius:50%;background:#f1eaffeb;box-shadow:0 0 12px #dbd1ff;border:1px solid #fff;}
.dashboard-greeting {font-weight:700;font-size:14px;margin:0;line-height:1.35;overflow-wrap:anywhere;}
.dashboard-date {font-size:10px;margin:4px 0 0;color:var(--muted);}
.dashboard-brand {position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;min-height:112px;padding:22px 10px 8px;text-align:center;}
.dashboard-brand .maya-art {position:absolute;width:105px;height:68px;top:-12px;right:28%;opacity:.8;}
.dashboard-brand h1 {position:relative;margin:0;color:#fff0c9;font-size:clamp(30px,9vw,43px);line-height:1.25;text-shadow:0 0 12px #f0baff,0 2px 3px #45246d;}
.dashboard-brand p {position:relative;max-width:270px;margin:5px 0 0;font-size:12px;line-height:1.5;}
.theme-plain-light .dashboard-brand h1 {color:var(--ink);text-shadow:none;}
.theme-plain-light .dashboard-brand .maya-art {display:none;}
.dashboard-insight {min-height:144px;display:grid;grid-template-columns:34% 1fr;align-items:center;padding:10px;gap:4px;}
.insight-copy {min-width:0;}
.eyebrow {font-size:10px;margin:0 0 4px;}
.dashboard-insight h2 {font-size:17px;line-height:1.35;margin:0;}
.dashboard-insight p:not(.eyebrow) {font-size:11px;line-height:1.5;margin:6px 0;}
.primary-action {display:flex;align-items:center;justify-content:center;gap:5px;min-height:38px;width:100%;border:1px solid #f4e3ff;border-radius:25px;background:linear-gradient(#faf0ff,#ddd2ff);color:#281079;padding:7px 10px;text-decoration:none;font-size:12px;font-weight:700;box-shadow:0 0 10px #e9bcff88;}
.primary-action:disabled {opacity:.75;}
.theme-plain-light .primary-action {background:linear-gradient(#6e50ee,#4c2fce);color:white;border-color:#745bed;box-shadow:none;}
.dashboard-grid {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(3,minmax(94px,1fr));gap:7px;flex:1;}
.dashboard-card {min-width:0;display:grid;grid-template-columns:40% 1fr;position:relative;align-items:center;gap:3px;text-decoration:none;padding:7px 7px 7px 2px;border-radius:20px;}
.dashboard-card div {min-width:0;}
.dashboard-card h2 {margin:0;font-size:clamp(11px,3.25vw,14px);line-height:1.4;font-weight:750;}
.dashboard-card p {margin:5px 0 0;font-size:10px;line-height:1.45;color:var(--muted);padding-right:10px;}
.dashboard-card>.maya-icon {position:absolute;right:5px;bottom:10px;width:18px;height:18px;}
.card-saved,.card-astro {background:linear-gradient(135deg,#f7dfb285,#91afe252);}
.theme-plain-light .card-saved,.theme-plain-light .card-astro,.theme-plain-light .card-today {background:#fffbef;}
.maya-art {display:block;width:100%;aspect-ratio:1;position:relative;}
.illustration {display:block;width:100%;height:100%;background-image:url('/art/maya-features.png');background-size:400% 200%;background-repeat:no-repeat;}
.plain-icon {display:none;}
.theme-plain-light .illustration {display:none;}
.theme-plain-light .plain-icon {display:grid;place-items:center;margin:auto;width:48px;height:48px;border-radius:50%;background:#eeeaff;color:var(--accent);position:absolute;inset:0;}
.theme-plain-light .art-astro .plain-icon,.theme-plain-light .art-saved .plain-icon,.theme-plain-light .art-today .plain-icon,.theme-plain-light .art-orb .plain-icon {color:var(--gold);background:#fff1cf;}
.theme-plain-light .plain-icon .maya-icon {width:28px;height:28px;}
.dashboard-bottom-nav {display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:2px;position:sticky;bottom:max(8px,env(safe-area-inset-bottom));z-index:4;background:#eae9fff0;color:#32236d;border:1px solid #fff;border-radius:25px;padding:6px;backdrop-filter:blur(18px);margin-top:auto;min-height:64px;box-shadow:0 2px 14px #543e8433;}
.dashboard-bottom-nav a {display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-height:50px;text-decoration:none;border-radius:17px;font-size:10px;}
.dashboard-bottom-nav [aria-current='page'] {background:#d8ccff;color:#4321c2;box-shadow:inset 0 0 10px #fff;}
.theme-astral-gold .dashboard-bottom-nav [aria-current='page'] {background:#f7e1ac;color:#8b5414;}
.app-header {display:flex;align-items:center;gap:8px;min-height:48px;position:relative;z-index:5;}
.app-header>img {width:42px;height:42px;flex:0 0 42px;object-fit:contain;}
.app-header>span {font-weight:700;font-size:18px;}
.app-menu {margin-left:auto;}
.app-menu summary {display:grid;place-items:center;min-width:42px;min-height:42px;cursor:pointer;list-style:none;border-radius:50%;background:var(--surface);}
.app-menu summary::-webkit-details-marker {display:none;}
.app-menu nav {position:absolute;right:0;top:54px;padding:8px;width:230px;max-height:70svh;overflow:auto;border-radius:18px;background:var(--field);color:var(--field-ink);box-shadow:0 10px 30px #121c4855;}
.app-menu nav a {display:block;text-decoration:none;padding:12px;min-height:44px;border-radius:10px;}
.app-menu nav a[aria-current] {background:#d9d0ff;}
.feature-screen,.account-screen,.screen-state {padding:6px 3px 18px;}
.feature-screen h1,.account-screen h1,.screen-state h1 {font-size:25px;line-height:1.4;margin:10px 0;}
.hero-kicker {font-size:11px;}
.hero-copy,.feature-screen p,.account-screen p {font-size:13px;line-height:1.6;}
.feature-hero {text-align:center;position:relative;}
.feature-hero p {margin:0;}
.feature-hero>.maya-art {width:175px;max-height:190px;margin:5px auto;}
.theme-plain-light .feature-hero>.maya-art {width:74px;height:74px;}
.inner-panel,.journey-card {padding:18px;margin:12px 0;border-radius:22px;}
.journey-card {background:var(--surface);border:1px solid var(--line);}
.inner-panel h2 {font-size:18px;}
.inner-panel label,.dream-screen label,.account-screen label,.language-picker {display:grid;gap:7px;font-size:13px;}
.inner-panel label+label {margin-top:14px;}
input,textarea,select {width:100%;min-width:0;min-height:44px;border:1px solid #c8b9ed;border-radius:13px;background:var(--field);color:var(--field-ink);padding:10px;}
textarea {resize:vertical;}
fieldset {min-width:0;}
.inner-panel .primary-action {margin-top:16px;}
.chat-panel {text-align:center;display:flex;flex-direction:column;min-height:235px;align-items:center;}
.chat-panel>.maya-icon {width:48px;height:48px;}
.chat-composer {display:flex;gap:7px;align-items:center;width:100%;margin-top:auto;}
.chat-composer button {border-radius:50%;padding:8px;border:0;background:#7050de;color:white;}
.theme-selector {padding:0;margin:8px 0 20px;border:0;}
.theme-selector legend {font-size:14px;font-weight:700;margin-bottom:10px;}
.theme-choices {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}
.theme-choices button {padding:5px;display:flex;flex-direction:column;gap:7px;align-items:center;background:var(--field);color:var(--field-ink);border:2px solid transparent;border-radius:14px;font-size:10px;min-width:0;}
.theme-choices [aria-pressed='true'] {border-color:#7653e3;box-shadow:0 0 0 1px #fff;}
.theme-swatch {width:100%;height:62px;border-radius:9px;background-size:cover;background-position:top;}
.swatch-astral-blue {background-image:url('/art/astral-blue.png');}
.swatch-astral-gold {background-image:url('/art/astral-gold.png');}
.swatch-plain-light {background:linear-gradient(135deg,#fff,#ecedff);border:1px solid #d6c6ff;}
.settings-row {border-bottom:1px solid var(--line);padding:10px 0;}
.settings-row summary {cursor:pointer;min-height:36px;}
.preview-status {font-size:11px!important;text-align:center;padding:7px;background:#16305080;border-radius:12px;}
.theme-plain-light .preview-status {background:#e6e1ff;}
.account-screen form {display:grid;gap:12px;margin:15px 0;}
.account-screen button,.history-screen button,.dream-screen button,.workspace button {min-height:44px;padding:9px 14px;border:1px solid var(--line);border-radius:14px;background:var(--field);color:var(--field-ink);}
.account-screen button:disabled,.dream-screen button:disabled,.workspace button:disabled {opacity:.6;}
.auth-modes {display:flex;gap:8px;}
.auth-modes [aria-pressed='true'] {background:#d0c3ff;}
.language-picker {margin-block:15px;}
.account-email {overflow-wrap:anywhere;}
.history-list {list-style:none;padding:0;display:grid;gap:12px;}
.history-content {white-space:pre-wrap;overflow-wrap:anywhere;}
.history-screen summary {min-height:44px;cursor:pointer;}
.history-confirm button+button {margin-left:10px;}
.dream-screen fieldset {display:grid;gap:12px;border:1px solid var(--line);border-radius:22px;background:var(--surface);padding:16px;}
.dream-result {overflow-wrap:anywhere;}
.journey-action {display:inline-flex;justify-content:center;padding:12px;min-height:44px;margin:8px 0;text-decoration:none;border:1px solid var(--line);border-radius:14px;background:var(--surface);}
.live-art {height:130px;width:130px;margin:0 auto;background:url('/art/maya-features.png') 0 0/400% 200%;}
.skip-link {position:fixed;z-index:20;top:8px;left:8px;transform:translateY(-200%);}
.skip-link:focus {transform:translateY(0);padding:12px;background:white;color:#211465;}
.workspace-shell {width:min(100%,1200px);}
.workspace-shell::before {max-width:1200px;}
.workspace {padding:12px;}
.workspace header {max-width:600px;margin:auto;}
.workspace-tabs {display:flex;justify-content:center;gap:10px;margin:20px 0;flex-wrap:wrap;}
.workspace-tabs [aria-pressed='true'] {background:#d7c8ff;}
.workspace iframe {display:block;width:min(100%,430px);height:800px;border:1px solid var(--line);border-radius:25px;margin:16px auto;background:#eee;}
.workspace>a {display:block;text-align:center;}
@media (min-height:780px) { .maya-shell:has(.dashboard-home) {height:100dvh;} }
@media (max-height:740px) { .dashboard-brand {min-height:82px;padding-top:14px;} .dashboard-brand h1 {font-size:32px;} .dashboard-brand>.maya-art {width:75px;height:48px;} .dashboard-insight {min-height:130px;} .dashboard-grid {grid-template-rows:repeat(3,minmax(84px,1fr));} .dashboard-home {gap:7px;} }
@media (max-width:350px) { .maya-shell {padding-inline:8px;} .dashboard-greeting {font-size:12px;} .dashboard-avatar {width:42px;height:42px;flex-basis:42px;} .icon-button {width:38px;height:38px;} .dashboard-card {grid-template-columns:34% 1fr;} .dashboard-card h2 {font-size:11px;} .dashboard-card p {font-size:9px;} .dashboard-insight h2 {font-size:15px;} }
@media (prefers-reduced-transparency:reduce) { .glass {backdrop-filter:none;background:#405595;} .theme-plain-light .glass {background:white;} .theme-astral-gold .glass {background:#78576b;} }

/* Text contrast without covering the theme artwork. */
.theme-astral-blue .glass,.theme-astral-gold .glass {
  --ink:#27164e; --muted:#443552; color:var(--ink);
  --surface:linear-gradient(135deg,#ffffff8c,#eee7ff70);
}
.theme-astral-blue .dashboard-topbar,.theme-astral-blue .dashboard-brand,
.theme-astral-blue .feature-hero,.theme-astral-blue .app-header {
  color:#fff8ed; text-shadow:0 1px 2px #182853,0 0 4px #182853;
}
.theme-astral-gold .dashboard-topbar,.theme-astral-gold .dashboard-brand,
.theme-astral-gold .feature-hero,.theme-astral-gold .app-header {
  --muted:#34234e; color:#27164e; text-shadow:0 1px 2px #fff7e6,0 0 4px #fff7e6;
}
.theme-astral-gold .dashboard-brand h1 {color:#27164e;text-shadow:0 1px 2px #fff7e6,0 0 4px #fff7e6;}
.preview-status {background:transparent;color:var(--ink);text-shadow:0 1px 2px #182853;}
.theme-astral-gold .preview-status {color:#27164e;text-shadow:0 1px 2px #fff7e6;}
.theme-plain-light .preview-status {background:transparent;text-shadow:none;}
.maya-shell:has(.design-chat) {height:100dvh;min-height:0;}
.maya-shell:has(.design-chat) #maya-content {min-height:0;}
.design-chat {flex:1;min-height:0;display:flex;flex-direction:column;padding-bottom:0;}
.design-chat .feature-hero {text-align:left;flex:0 0 auto;}
.design-chat .feature-hero h1 {font-size:20px;margin:0;}
.design-chat .feature-hero p {font-size:12px;}
.design-chat .preview-status {margin:4px 0;}
.chat-panel {flex:1;min-height:0;align-items:stretch;text-align:left;margin:8px 0;padding:12px;}
.chat-conversation {flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;justify-content:center;text-align:center;}
.chat-conversation h2 {font-size:18px;margin:8px 0;}
.chat-composer {align-items:flex-end;flex-wrap:wrap;gap:8px;}
.chat-composer textarea {flex:1;min-width:0;max-height:140px;resize:none;}
.chat-composer button {width:44px;min-height:44px;display:grid;place-items:center;flex-shrink:0;}
.chat-composer button:disabled {opacity:.45;}
.voice-status {width:100%;font-size:12px;margin:0;min-height:20px;}

/* Compact Astro form, crystal composer, theme-matched controls. */
.maya-shell:has(.design-astro) {min-height:100dvh;}
.design-astro {padding-top:0;}
.design-astro .feature-hero {display:grid;grid-template-columns:1fr 66px;align-items:center;text-align:left;column-gap:8px;}
.design-astro .feature-hero h1 {font-size:21px;margin:4px 0;}
.design-astro .feature-hero p {grid-column:1;font-size:12px;}
.design-astro .feature-hero>.maya-art {grid-column:2;grid-row:1/3;width:66px;height:66px;margin:0;}
.design-astro .preview-status {margin:4px 0;font-size:10px!important;}
.design-astro .inner-panel {padding:14px;margin:8px 0;}
.design-astro .inner-panel label+label {margin-top:10px;}
.design-astro .inner-panel label {gap:4px;}
.design-astro .inner-panel input {min-height:42px;padding:8px;}
.design-astro .inner-panel .primary-action {margin-top:12px;}
.design-astro .inner-panel p {margin:8px 0 0;font-size:11px;}
.theme-astral-blue .inner-panel input,.theme-astral-blue .inner-panel textarea {background:#d5ddff94;}
.theme-astral-gold .inner-panel input,.theme-astral-gold .inner-panel textarea {background:#f8e6c691;}
.chat-composer {position:relative;display:grid;grid-template-columns:36px minmax(0,1fr) 36px;align-items:end;gap:4px;border:1px solid var(--line);border-radius:22px;padding:7px;background:var(--surface);box-shadow:inset 0 1px 0 #ffffff99;backdrop-filter:blur(12px);}
.chat-composer textarea {grid-column:2;grid-row:1;border:0;border-radius:0;background:transparent!important;min-height:38px;height:38px;max-height:130px;padding:7px 2px;box-shadow:none;font-size:14px;line-height:22px;overflow:auto;}
.chat-composer button {grid-row:1;width:36px;height:36px;min-height:36px;padding:6px;background:transparent;color:var(--field-ink);border:1px solid transparent;}
.chat-composer button:first-of-type {grid-column:1;}
.chat-composer button:last-of-type {grid-column:3;border-color:var(--line);background:#d6c9ff88;}
.theme-astral-gold .chat-composer button:last-of-type {background:#f6ce8188;color:#573510;}
.chat-composer button[aria-pressed='true'] {background:#d6c9ff99;border-color:var(--field-ink);}
.chat-composer .maya-icon {width:20px;height:20px;}
.voice-status {font-size:10px!important;line-height:1.4!important;margin:6px 2px 0;}
.chat-conversation:has(.chat-message) {justify-content:flex-start;text-align:left;gap:12px;}
.chat-message {padding:10px;border-radius:16px;background:var(--surface);overflow-wrap:anywhere;}
.chat-message p {white-space:pre-wrap;}
.message-actions {display:flex;gap:6px;align-items:center;}
.message-actions button {width:34px;min-height:34px;border:1px solid var(--line);border-radius:10px;background:transparent;color:inherit;display:grid;place-items:center;}
.message-actions button[aria-pressed='true'] {background:#d6c9ff88;}
.message-actions .maya-icon {width:17px;height:17px;}
@media(max-height:650px){.design-astro .feature-hero>.maya-art {width:46px;height:46px;} .design-astro .feature-hero h1 {font-size:18px;} .design-astro .inner-panel {padding:10px;} .design-astro .inner-panel label+label {margin-top:6px;}}

/* Owner-approved compact crystal header and full conversation workspace. */
.dashboard-avatar {background:linear-gradient(135deg,#eee5ff66,#f1cf8d44);border-color:#fff7d988;box-shadow:0 2px 10px #28154755,inset 0 1px 0 #ffffff66;backdrop-filter:blur(8px);}
.theme-plain-light .dashboard-avatar {background:#eeebff;box-shadow:0 2px 8px #54438422;}
.crystal-header {border:1px solid var(--line);border-radius:18px;padding:5px 7px;background:var(--surface);box-shadow:inset 0 1px 0 #ffffff88,0 3px 12px #28154722;backdrop-filter:blur(10px);}
.crystal-header>span {font-size:16px;}
.maya-shell:has(.design-dream),.maya-shell.conversation-shell {height:100dvh;min-height:0;}
.maya-shell:has(.design-dream) #maya-content {min-height:0;}
.design-dream {flex:1;min-height:0;display:flex;flex-direction:column;padding-bottom:0;}
.conversation-heading {position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.design-chat .chat-panel,.design-dream .chat-panel {margin:0;flex:1;min-height:0;border-radius:22px;}
.design-chat,.design-dream {padding:0;}
.design-settings .feature-hero {text-align:left;}
.design-settings .feature-hero h1 {font-size:21px;}
.design-settings .feature-hero p {font-size:12px;}
.design-astro .feature-hero>.maya-art {display:none;}
.design-astro .feature-hero {display:block;}
.astro-panel {padding:10px 14px!important;}
.kundli-heading {display:flex;align-items:center;gap:10px;}
.kundli-heading h2 {font-size:14px;white-space:nowrap;margin:0;}
.kundli-heading p {font-size:10px!important;margin:0!important;line-height:1.4!important;}
.kundli-chart {position:relative;width:180px;height:180px;margin:8px auto;color:#8a5719;background:linear-gradient(135deg,#e2d6ff55,#ffe0a455);border-radius:8px;}
.kundli-chart svg {width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.4;}
.kundli-house {position:absolute;transform:translate(-50%,-50%);width:34px;height:34px;min-height:34px;border:0;border-radius:50%;background:transparent;color:var(--field-ink);font-size:12px;padding:0;}
.kundli-house[aria-pressed='true'] {background:#f5cf8599;box-shadow:0 0 0 1px #956017;}
.kundli-detail {font-size:10px!important;margin:4px 0 8px!important;min-height:25px;}
.birth-fields {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;}
.birth-fields label:first-child,.birth-fields label:last-child {grid-column:1/-1;}
.design-astro .birth-fields label+label {margin-top:0;}
.design-astro .birth-fields label {font-size:12px;}
.astro-pending {text-align:center;}
@media(max-height:700px){.kundli-chart {width:150px;height:150px;} .design-astro .feature-hero p {display:none;} .design-astro .preview-status {font-size:9px!important;} .birth-fields {gap:6px;}}

/* One combined header; content stays above bottom navigation. */
.header-brand {
  display:flex; flex-direction:column; gap:2px;
  min-width:0; flex:1;
}
.header-brand strong {font-size:21px;line-height:1.25;}
.header-brand small {font-size:11px;line-height:1.3;}
.crystal-header {flex-shrink:0;margin:0;min-height:58px;}
.design-screen>.feature-hero,
.design-screen>.preview-status {
  position:absolute!important;width:1px;height:1px;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;
}
.maya-shell:has(.design-screen) {
  height:100dvh;min-height:0;gap:6px;
}
.maya-shell:has(.design-screen) #maya-content {
